#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    long long key;
    unsigned int pri;
    int cnt, sz;
    struct Node *l, *r;
} Node;

static unsigned int seed = 123456789;

unsigned int rng(void) {
    seed ^= seed << 13;
    seed ^= seed >> 17;
    seed ^= seed << 5;
    return seed;
}

int sz(Node *t) {
    return t ? t->sz : 0;
}

void pull(Node *t) {
    if (t) t->sz = sz(t->l) + sz(t->r) + t->cnt;
}

Node *newNode(long long key) {
    Node *n = (Node *)malloc(sizeof(Node));
    n->key = key;
    n->pri = rng();
    n->cnt = 1;
    n->sz = 1;
    n->l = n->r = NULL;
    return n;
}

Node *rotateRight(Node *y) {
    Node *x = y->l;
    y->l = x->r;
    x->r = y;
    pull(y);
    pull(x);
    return x;
}

Node *rotateLeft(Node *x) {
    Node *y = x->r;
    x->r = y->l;
    y->l = x;
    pull(x);
    pull(y);
    return y;
}

Node *insert(Node *t, long long key) {
    if (!t) return newNode(key);

    if (key == t->key) {
        t->cnt++;
        t->sz++;
        return t;
    }

    if (key < t->key) {
        t->l = insert(t->l, key);
        if (t->l->pri < t->pri) t = rotateRight(t);
    } else {
        t->r = insert(t->r, key);
        if (t->r->pri < t->pri) t = rotateLeft(t);
    }

    pull(t);
    return t;
}

int countLE(Node *t, long long key) {
    if (!t) return 0;

    if (key < t->key) {
        return countLE(t->l, key);
    } else if (key > t->key) {
        return sz(t->l) + t->cnt + countLE(t->r, key);
    } else {
        return sz(t->l) + t->cnt;
    }
}

int main(void) {
    int N;
    scanf("%d", &N);

    Node *root = NULL;
    long long prevPenalty = 0;

    for (int i = 0; i < N; i++) {
        long long x, y;
        scanf("%lld %lld", &x, &y);

        long long realX = x + prevPenalty;
        long long realY = y + prevPenalty;

        long long dist = realX * realX + realY * realY;

        int penalty = countLE(root, dist);
        printf("%d\n", penalty);

        root = insert(root, dist);
        prevPenalty = penalty;
    }

    return 0;
}
